// Turns the pasted searches into one scrape each.
//
// The brief carries URLs rather than a city because building a portal's search
// URL from a typed place name only works for the portals that spell a place
// into the path, and those are not the portals worth scraping: the one that
// can be addressed that way returned ten homes a page from behind the heaviest
// bot protection, while the richest source keys its cities on an internal id
// no form can produce.
//
// Pasting the URL also hands the filtering back to the portal, which is far
// better at it than anything reconstructable here — price, beds, property
// type, a drawn map region — so the scrape starts already narrowed.

const brief = $input.first().json;

const urls = String(brief['Listing search URLs'] ?? '')
  .split(/[\r\n,]+/)
  .map((line) => line.trim())
  .filter(Boolean);

const valid = urls.filter((url) => /^https?:\/\/[^\s/]+\.[^\s/]+/i.test(url));
if (!valid.length) {
  throw new Error('Paste at least one listing search URL, starting with https://');
}

// Each search mints a job and is charged for it, so the count is worth bounding.
if (valid.length > 5) {
  throw new Error('Five searches at a time is the limit — each one mints a Gluecrawl job.');
}

const maxPages = Math.min(Math.max(Number(brief['Max pages per search']) || 5, 1), 20);
const maxPrice = Number(brief['Max price']) || null;
const minBeds = Number(brief['Minimum bedrooms']) || null;

const hostOf = (url) => (url.split('/')[2] || '').replace(/^www\./, '');
const label = [...new Set(valid.map(hostOf))].join(', ');

return valid.map((search_url) => ({
  json: {
    search_url,
    portal: hostOf(search_url),
    label,
    max_pages: maxPages,
    max_price: maxPrice,
    min_beds: minBeds,
    searched_at: $now.toISO(),
  },
}));

// Works out what each home should cost, and keeps the ones asking less.
//
// The comparison is made inside this one scrape: a home is measured against
// other listings in its own ZIP of roughly its own size, never against a
// national figure or a previous week. That is what lets the first run say
// something — there is no history to accumulate, and a level like "the median
// is $285/sqft" is a fact the reader already had.
//
// What this cannot see is why a home is cheap. Condition, a busy road, a lease
// on the land, an HOA: all of it is invisible in a listing card, and any of it
// can explain the whole gap. The output is a list of homes worth a question,
// not a list of bargains.

const MIN_COHORT = 5;         // fewer than this and the median is one opinion
const SIZE_BAND = 0.3;        // compare against homes within +/- 30% of the floor area
const MIN_DISCOUNT_PCT = 8;   // under this, the noise in a small median swamps the signal
const MAX_DISCOUNT_PCT = 50;  // above this it is almost always the data, not the price
const SHORTLIST_SIZE = 10;

const brief = $('Build the Searches').first().json;

function toNumber(value) {
  if (typeof value === 'number') return Number.isFinite(value) ? value : null;
  if (typeof value !== 'string') return null;
  const millions = /([\d.]+)\s*M\b/i.exec(value);
  if (millions) return Math.round(parseFloat(millions[1]) * 1000000);
  const parsed = parseFloat(value.replace(/,/g, '').replace(/[^\d.]/g, ''));
  return Number.isFinite(parsed) && parsed > 0 ? parsed : null;
}

// The Code sandbox does not expose URL, and parsing through it fails silently.
function canonicalUrl(value) {
  if (typeof value !== 'string') return null;
  const withoutQuery = value.trim().split('#')[0].split('?')[0];
  return /^https?:\/\/[^/]+/i.test(withoutQuery) ? withoutQuery.replace(/\/+$/, '') : null;
}

// Portals disagree about the tail of an address — one writes "3228 Jewelfish
// Cove, Austin TX 78728", another glues the city straight on as "3228
// Jewelfish CoveAustin, TX 78728". The head never varies, so identity is the
// street number, the first word of the street, and the ZIP.
function houseKey(address, zip) {
  const head = String(address ?? '').trim().match(/^(\d+)\s+([A-Za-z]+)/);
  return head && zip ? (head[1] + ' ' + head[2] + ' ' + zip).toLowerCase() : null;
}

// A US address ends with its ZIP, so the last five-digit token is the ZIP even
// when the street number is also five digits. The dedicated column cannot be
// trusted ahead of it — the mapper fills it with the street number on some rows.
function toZip(row) {
  const inAddress = String(row.address ?? '').match(/\b\d{5}\b/g);
  if (inAddress) return inAddress[inAddress.length - 1];
  const field = row.zip_code;
  if (typeof field === 'number' && Number.isInteger(field) && field >= 501 && field <= 99950) {
    return String(field).padStart(5, '0');
  }
  const match = String(field ?? '').match(/\b\d{5}\b/);
  return match ? match[0] : null;
}

function median(values) {
  if (!values.length) return null;
  const sorted = [...values].sort((a, b) => a - b);
  const mid = Math.floor(sorted.length / 2);
  return sorted.length % 2 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
}

function quantile(sorted, q) {
  const pos = (sorted.length - 1) * q;
  const base = Math.floor(pos);
  const next = sorted[base + 1] ?? sorted[base];
  return sorted[base] + (pos - base) * (next - sorted[base]);
}

const byKey = new Map();
for (const item of $input.all()) {
  const row = item.json.data ?? item.json;
  const listingUrl = canonicalUrl(row.listing_url);
  const zip = toZip(row);
  const key = houseKey(row.address, zip) ?? listingUrl;
  if (!key || byKey.has(key)) continue;

  const price = toNumber(row.price);
  const sqft = toNumber(row.sqft);
  byKey.set(key, {
    address: String(row.address ?? '').trim(),
    zip_code: zip ?? '',
    listing_url: listingUrl ?? '',
    source: listingUrl ? (listingUrl.split('/')[2] || '').replace('www.', '') : '',
    price,
    sqft,
    beds: toNumber(row.beds),
    baths: toNumber(row.baths),
    price_per_sqft: price && sqft ? Math.round(price / sqft) : null,
  });
}

const all = [...byKey.values()];
const priced = all.filter((row) => row.price_per_sqft > 0 && row.zip_code);

// A mis-parsed price would otherwise become a comparable and drag every home
// measured against it.
const ppsfSorted = priced.map((row) => row.price_per_sqft).sort((a, b) => a - b);
let clean = priced;
if (ppsfSorted.length >= 8) {
  const q1 = quantile(ppsfSorted, 0.25);
  const q3 = quantile(ppsfSorted, 0.75);
  const fence = 1.5 * (q3 - q1);
  clean = priced.filter((row) => row.price_per_sqft >= q1 - fence && row.price_per_sqft <= q3 + fence);
}

/**
 * Comparable homes, and never any further out than the ZIP.
 *
 * Widening to the whole city looks like generosity and is the one change that
 * makes this workflow lie: a modest home in a cheap ZIP is 50% under a
 * city-wide median every single time, so every cheap neighbourhood fills the
 * shortlist and nothing in it is a bargain. A home whose own ZIP has too few
 * comparables cannot be valued here, and is left out rather than flattered.
 */
function cohortFor(subject) {
  const sameZip = clean.filter((row) => row !== subject && row.zip_code === subject.zip_code);
  const sameSize = sameZip.filter((row) => Math.abs(row.sqft - subject.sqft) <= subject.sqft * SIZE_BAND);
  if (sameSize.length >= MIN_COHORT) {
    return { rows: sameSize, basis: 'ZIP ' + subject.zip_code + ', similar size' };
  }
  if (sameZip.length >= MIN_COHORT) {
    return { rows: sameZip, basis: 'ZIP ' + subject.zip_code + ', any size' };
  }
  return null;
}

const scored = [];
for (const subject of clean) {
  const cohort = cohortFor(subject);
  if (!cohort) continue;
  const expectedPpsf = median(cohort.rows.map((row) => row.price_per_sqft));
  const expectedPrice = Math.round(expectedPpsf * subject.sqft);
  scored.push({
    ...subject,
    expected_price: expectedPrice,
    expected_price_per_sqft: Math.round(expectedPpsf),
    discount_pct: Math.round(((expectedPrice - subject.price) / expectedPrice) * 1000) / 10,
    cohort_size: cohort.rows.length,
    basis: cohort.basis,
  });
}

const withinBrief = (row) =>
  (!brief.max_price || row.price <= brief.max_price) && (!brief.min_beds || (row.beds ?? 0) >= brief.min_beds);

const matching = scored.filter(withinBrief);
// A brief nobody can meet should say so rather than quietly widening itself.
const relaxed = matching.length === 0 && scored.length > 0;
const pool = relaxed ? scored : matching;

const shortlist = pool
  // A gap wider than half the value of the street is nearly always a mis-read
  // floor area or a different kind of property — a mobile home, a share, a
  // plot — rather than a house going cheap.
  .filter((row) => row.discount_pct >= MIN_DISCOUNT_PCT && row.discount_pct <= MAX_DISCOUNT_PCT)
  // Nobody can act on a listing that withholds its address.
  .filter((row) => /^\d+\s+[A-Za-z]/.test(row.address))
  .sort((a, b) => b.discount_pct - a.discount_pct)
  .slice(0, SHORTLIST_SIZE);

// Where a buyer on this brief can actually shop.
const inBudgetByZip = {};
for (const row of matching) inBudgetByZip[row.zip_code] = (inBudgetByZip[row.zip_code] ?? 0) + 1;
const zipDepth = Object.entries(inBudgetByZip)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 12);

const bySource = {};
for (const row of all) bySource[row.source || 'unknown'] = (bySource[row.source || 'unknown'] ?? 0) + 1;

const money = (value) => (value ? '$' + Math.round(Number(value)).toLocaleString('en-US') : 'n/a');

// One portal runs the city onto the end of the street with no separator, so a
// label cut at the first comma reads "143 Desert Willow WayAustin". Splitting
// where a lower-case or digit meets a capital puts the boundary back.
function displayAddress(row) {
  const spaced = String(row.address ?? '').replace(/([a-z0-9])([A-Z])/g, '$1 $2');
  const head = spaced.match(/^\d+(?:\s+[A-Za-z0-9#'-]+){1,3}/);
  return head ? head[0] : spaced.split(',')[0].slice(0, 28);
}

const criteria =
  brief.label +
  (brief.max_price ? ', under ' + money(brief.max_price) : '') +
  (brief.min_beds ? ', ' + brief.min_beds + '+ beds' : '');

const briefText = [
  'SEARCH: ' + criteria,
  'Listings gathered: ' + all.length + ' across ' + Object.keys(bySource).length + ' portals (' + Object.entries(bySource).map(([s, n]) => s + ' ' + n).join(', ') + ')',
  'Priced with floor area, after removing outliers: ' + clean.length,
  'Valued against their own ZIP: ' + scored.length + ' (the rest had too few comparable listings on their own streets)',
  'Matching the brief: ' + matching.length,
  relaxed ? 'NOTE: nothing matched the budget or bedroom minimum, so these are the best-value homes in the city regardless of the brief.' : '',
  '',
  'SHORTLIST — asking below what comparable homes suggest',
  ...(shortlist.length
    ? shortlist.flatMap((row, index) => [
        index + 1 + '. ' + displayAddress(row) + '  [' + row.zip_code + ']',
        '   asking ' + money(row.price) + ' (' + money(row.price_per_sqft) + '/sqft) for ' + row.sqft.toLocaleString('en-US') + ' sqft, ' + (row.beds ?? '?') + ' bed, ' + (row.baths ?? '?') + ' bath',
        '   comparable homes suggest ' + money(row.expected_price) + ' (' + money(row.expected_price_per_sqft) + '/sqft) — asking ' + row.discount_pct + '% less',
        '   basis: ' + row.basis + ', ' + row.cohort_size + ' comparable listings',
        '   ' + (row.listing_url || 'no link'),
      ])
    : ['   none: no home in this search is asking materially below its comparables']),
  '',
  'WHERE THE MATCHING HOMES ARE',
  ...(zipDepth.length ? zipDepth.map(([zip, count]) => '- ' + zip + ': ' + count + ' listings') : ['- none']),
].filter(Boolean).join('\n');

return [
  {
    json: {
      searched_at: brief.searched_at,
      label: brief.label,
      max_price: brief.max_price,
      min_beds: brief.min_beds,
      criteria,
      gathered: all.length,
      compared: clean.length,
      valued: scored.length,
      matching: matching.length,
      relaxed,
      sources: Object.entries(bySource).map(([source, listing_count]) => ({ source, listing_count })),
      shortlist,
      brief: briefText,
      discount_labels: shortlist.map(displayAddress),
      discount_values: shortlist.map((row) => row.discount_pct),
      zip_labels: zipDepth.map(([zip]) => zip),
      zip_values: zipDepth.map(([, count]) => count),
    },
  },
];

// Binary does not travel with $json, so a node that reads only the model's text
// drops the charts. Naming both fields here is what makes a Gmail or Slack node
// downstream a one-node change.

const stats = $('Rank by Value').first().json;

// The model is told not to restate the shortlist and does it anyway often
// enough to matter, rounding its own way as it goes. The table below is the
// authoritative one, so any table it emits is a second answer to the same
// question — stripped here rather than argued with in the prompt.
const commentary = String($input.first().json.text ?? '')
  .split('\n')
  .filter((line) => !line.trim().startsWith('|'))
  .join('\n')
  .replace(/\n{3,}/g, '\n\n')
  .trim();
const money = (value) => (value ? '$' + Math.round(Number(value)).toLocaleString('en-US') : 'n/a');

const report = [
  '# ' + stats.shortlist.length + ' homes worth a question',
  '',
  '**Search:** ' + stats.criteria,
  '**' + stats.gathered + ' listings gathered** · ' + stats.compared + ' comparable on price and floor area · ' + stats.matching + ' matching the brief',
  stats.relaxed ? '' : '',
  ...(stats.relaxed ? ['', '> Nothing matched the budget or bedroom minimum, so this is the best value in the city regardless of the brief.'] : []),
  '',
  commentary.trim(),
  '',
  '## The shortlist',
  '',
  '| Home | Asking | Comparables suggest | Under by | Based on |',
  '| --- | --- | --- | --- | --- |',
  ...stats.shortlist.map(
    (row) =>
      '| [' + (row.address.split(',')[0] || row.address) + '](' + (row.listing_url || '#') + ') | ' +
      money(row.price) + ' | ' + money(row.expected_price) + ' | ' + row.discount_pct + '% | ' +
      row.cohort_size + ' homes, ' + row.basis + ' |',
  ),
  '',
  '---',
  '',
  'A gap is a question, not a discount: condition, a busy road, a land lease or an HOA can explain all of it and none of them appear on a listing card.',
].filter((line) => line !== null).join('\n');

return [
  {
    json: { ...stats, commentary, report },
    binary: {
      ...($('How Far Under Expected').first().binary ?? {}),
      ...($('Where the Matching Homes Are').first().binary ?? {}),
    },
  },
];
